    t9.sub_chn_eff_date as SUB_CHANNEL_EFFECTIVE_DATE,
    t9.subimd_yn as SUB_INTERMEDIARY_INDICATOR,
    t7.tds_rate as TDS_RATE,
    coalesce(t2.tax_code, t3.tax_code) as TAX_TYPE,
    t9.intermediary_band as TIER_CODE,
    t5.payment_req_date_time as TRANSACTION_DATE,
    coalesce(t1.utgst_amt, t5.utgst_amt) as UTGST_AMOUNT
from t0
full outer join t1 on t1.HUB_POLICY_BK__BASE_POLICY_REF = t0.HUB_POLICY_BK__CONTRACT_ID
full outer join t2 on t2.HUB_POLICY_BK__REFERENCE_ID = coalesce(t0.HUB_POLICY_BK__CONTRACT_ID, t1.HUB_POLICY_BK__BASE_POLICY_REF)
full outer join t3 on t3.HUB_POLICY_BK__REG_NO = coalesce(t0.HUB_POLICY_BK__CONTRACT_ID, t1.HUB_POLICY_BK__BASE_POLICY_REF, t2.HUB_POLICY_BK__REFERENCE_ID)
full outer join t4 on t4.HUB_POLICY_BK__POLICY_REF = coalesce(t0.HUB_POLICY_BK__CONTRACT_ID, t1.HUB_POLICY_BK__BASE_POLICY_REF, t2.HUB_POLICY_BK__REFERENCE_ID, t3.HUB_POLICY_BK__REG_NO)
full outer join t5 on t5.HUB_POLICY_BK__CONTRACT_ID = coalesce(t0.HUB_POLICY_BK__CONTRACT_ID, t1.HUB_POLICY_BK__BASE_POLICY_REF, t2.HUB_POLICY_BK__REFERENCE_ID, t3.HUB_POLICY_BK__REG_NO, t4.HUB_POLICY_BK__POLICY_REF)
full outer join t6 on t6.HUB_POLICY_BK__POLICY_NO = coalesce(t0.HUB_POLICY_BK__CONTRACT_ID, t1.HUB_POLICY_BK__BASE_POLICY_REF, t2.HUB_POLICY_BK__REFERENCE_ID, t3.HUB_POLICY_BK__REG_NO, t4.HUB_POLICY_BK__POLICY_REF, t5.HUB_POLICY_BK__CONTRACT_ID)
full outer join t7 on t7.HUB_POLICY_BK__POLICY = coalesce(t0.HUB_POLICY_BK__CONTRACT_ID, t1.HUB_POLICY_BK__BASE_POLICY_REF, t2.HUB_POLICY_BK__REFERENCE_ID, t3.HUB_POLICY_BK__REG_NO, t4.HUB_POLICY_BK__POLICY_REF, t5.HUB_POLICY_BK__CONTRACT_ID, t6.HUB_POLICY_BK__POLICY_NO)
full outer join t8 on t8.HUB_POLICY_BK__POLICY_NO = coalesce(t0.HUB_POLICY_BK__CONTRACT_ID, t1.HUB_POLICY_BK__BASE_POLICY_REF, t2.HUB_POLICY_BK__REFERENCE_ID, t3.HUB_POLICY_BK__REG_NO, t4.HUB_POLICY_BK__POLICY_REF, t5.HUB_POLICY_BK__CONTRACT_ID, t6.HUB_POLICY_BK__POLICY_NO, t7.HUB_POLICY_BK__POLICY)
full outer join t9 on t9.HUB_PARTY_BK__INTERMEDIARY_ID = coalesce(t0.HUB_PARTY_BK__USER_ID, t5.HUB_PARTY_BK__PART_ID, t7.HUB_PARTY_BK__HOSPITAL_ID)
